package com.horizonssmp.gov.common;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;

/**
 * One request from the dashboard to the server.
 *
 * <p>{@code reqId} is generated by the sender and echoed back in the {@link ActionResult}, so a
 * client with more than one request in flight can match replies without guessing. It is an
 * identifier, not a secret and not a capability: the server never trusts anything else about the
 * request beyond the op and the payload, and it never trusts the payload's claim about who the
 * target is.
 *
 * <p>The payload is a plain string map on purpose. It keeps the request shape inspectable in a log
 * line, it cannot carry a serialized object that would deserialize into something unexpected, and
 * every value still has to be parsed and validated by a handler on the server. Keys are short names
 * such as {@code target}, {@code article}, {@code band}; the payload-size guard in the dispatcher
 * is what keeps a hostile client from sending a megabyte of keys.
 *
 * @param op the action requested
 * @param payload the request arguments, never {@code null}
 * @param reqId the correlation id, never {@code null}
 */
public record ActionRequest(OpCode op, Map<String, String> payload, String reqId) {

    public ActionRequest {
        if (op == null) {
            throw new IllegalArgumentException("ActionRequest requires an op");
        }
        reqId = reqId == null || reqId.isBlank() ? UUID.randomUUID().toString() : reqId;
        final Map<String, String> copy = new LinkedHashMap<>();
        if (payload != null) {
            for (final Map.Entry<String, String> entry : payload.entrySet()) {
                if (entry.getKey() != null && entry.getValue() != null) {
                    copy.put(entry.getKey(), entry.getValue());
                }
            }
        }
        payload = Collections.unmodifiableMap(copy);
    }

    /** A request with a freshly generated correlation id. */
    public static ActionRequest of(final OpCode op, final Map<String, String> payload) {
        return new ActionRequest(op, payload, UUID.randomUUID().toString());
    }

    /** Reads a payload value, or {@code fallback} when absent. */
    public String get(final String key, final String fallback) {
        final String value = payload.get(key);
        return value == null ? fallback : value;
    }
}
